package com.faijan.interviewhub.config;
import com.faijan.interviewhub.entity.Question;import com.faijan.interviewhub.repository.QuestionRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import java.util.List;
@Configuration public class DataSeeder {
 @Bean CommandLineRunner seed(QuestionRepository repo){return args->{if(repo.count()==0)repo.saveAll(List.of(
 new Question("What is the difference between JDK, JRE and JVM?","Java","Core Java","Beginner","JVM executes bytecode. JRE provides the JVM and runtime libraries. JDK includes development tools such as the compiler plus the runtime.","javac Hello.java\njava Hello"),
 new Question("What is the contract between equals() and hashCode()?","Java","Collections","Intermediate","If two objects are equal according to equals(), they must return the same hashCode. Unequal objects may still share a hash code.","a.equals(b) == true implies a.hashCode() == b.hashCode()"),
 new Question("What is dependency injection in Spring?","Spring Boot","IoC and DI","Beginner","Dependency Injection means the container supplies an object with the dependencies it needs instead of the object creating them itself.","@Service\nclass OrderService {\n  private final PaymentService payment;\n  OrderService(PaymentService payment) { this.payment = payment; }\n}"),
 new Question("What is the difference between @Component, @Service and @Repository?","Spring Boot","Spring Core","Intermediate","All register Spring-managed beans. Service communicates intent for business logic; Repository marks persistence components and participates in persistence exception translation.","@Repository\nclass StudentRepositoryAdapter {}"),
 new Question("What is the difference between JPA and Hibernate?","Hibernate","ORM","Intermediate","JPA (now Jakarta Persistence) is a specification. Hibernate ORM is an implementation that provides ORM functionality and implements the persistence API.","@Entity\nclass Student { @Id Long id; }"),
 new Question("What is the purpose of Spring Data JPA?","Spring Data JPA","Repositories","Beginner","It reduces repository boilerplate by generating implementations for repository interfaces and supports derived queries, paging and sorting.","interface StudentRepository extends JpaRepository<Student, Long> {}"),
 new Question("What is the N+1 query problem?","Hibernate","Performance","Advanced","It occurs when one query loads parent rows and additional queries are issued for each related row. Fetch joins, entity graphs or batch fetching can help when used carefully.","@EntityGraph(attributePaths = \"department\")\nOptional<Student> findById(Long id);"),
 new Question("What is REST?","REST API","HTTP","Beginner","REST is an architectural style for networked systems. RESTful APIs commonly expose resources through URLs and use HTTP methods and status codes.","GET /api/students/10\nPOST /api/students"),
 new Question("What is the difference between PUT and PATCH?","REST API","HTTP Methods","Intermediate","PUT generally replaces the target resource representation. PATCH applies a partial modification.","PUT /api/users/5\nPATCH /api/users/5"),
 new Question("What is Redis commonly used for in backend applications?","Redis","Caching","Beginner","Redis is an in-memory data store often used for caching, counters, rate limiting, queues and other low-latency data access patterns.","SET user:42 Faijan\nGET user:42"),
 new Question("What are Kafka topics, producers and consumers?","Kafka","Messaging","Beginner","A producer publishes events to a topic. Consumers subscribe to topics and process events. Topics are divided into partitions for scale and ordering within a partition.","producer.send(new ProducerRecord<>(\"orders\", \"order-1\", payload));"),
 new Question("What is a microservice?","Microservices","Architecture","Beginner","A microservice is a small, independently deployable service organized around a business capability. It communicates with other services through well-defined contracts.","Catalog Service -> REST/Event -> Order Service"),
 new Question("What is JWT used for?","Spring Security","Security","Intermediate","A JSON Web Token is a compact claims format often used to carry signed authentication or authorization information between parties. Validate signature, issuer, audience and expiry.","Authorization: Bearer <token>"),
 new Question("What is the difference between process and thread?","Java","Multithreading","Beginner","A process is an executing program with its own resources. Threads are execution paths within a process and share process memory.","Thread worker = new Thread(task); worker.start();"),
 new Question("What is database indexing?","MySQL","Database","Beginner","An index is a data structure that can speed up lookups and sorting, at the cost of extra storage and write overhead.","CREATE INDEX idx_student_email ON students(email);")
 ));};}
}
